"use client";

export default function PricingTierEditor({ tiers, onChange }) {
  const update = (index, field, value) => onChange(tiers.map((tier, tierIndex) => tierIndex === index ? { ...tier, [field]: value } : tier));
  return <div><div className="flex items-center justify-between gap-4"><div><h3 className="font-bold">Wholesale Pricing</h3><p className="mt-1 text-xs text-slate-500">Optional quantity-based unit prices.</p></div><button type="button" onClick={() => onChange([...tiers, { minQty: "", price: "" }])} className="min-h-10 rounded-lg border border-orange-300 px-3 text-sm font-bold text-orange-800">Add tier</button></div>{tiers.length > 0 && <div className="mt-4 space-y-3">{tiers.map((tier, index) => <div key={index} className="grid gap-3 rounded-xl bg-slate-50 p-3 sm:grid-cols-[1fr_1fr_auto] sm:items-end"><label className="text-xs font-bold text-slate-700">Minimum Quantity<input type="number" min="1" step="1" value={tier.minQty} onChange={(event) => update(index, "minQty", event.target.value)} className="mt-1 min-h-11 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm"/></label><label className="text-xs font-bold text-slate-700">Price Per Unit<input type="number" min="0.01" step="0.01" value={tier.price} onChange={(event) => update(index, "price", event.target.value)} className="mt-1 min-h-11 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm"/></label><button type="button" onClick={() => onChange(tiers.filter((_, tierIndex) => tierIndex !== index))} className="min-h-11 rounded-lg border border-rose-200 px-3 text-sm font-bold text-rose-700">Remove</button></div>)}</div>}</div>;
}
